void config_type(uint32_t i, channels::crop_type &g) {
  switch (i) {
    case 0: config_type_barley(g); return;
    case 1: config_type_beans(g); return;
    case 2: config_type_cabbage(g); return;
    case 3: config_type_carrot(g); return;
    case 4: config_type_flax(g); return;
    case 5: config_type_grapes(g); return;
    case 6: config_type_lavender(g); return;
    case 7: config_type_lettuce(g); return;
    case 8: config_type_maize(g); return;
    case 9: config_type_oats(g); return;
    case 10: config_type_onion(g); return;
    case 11: config_type_potato(g); return;
    case 12: config_type_pumpkin(g); return;
    case 13: config_type_sunflower(g); return;
    case 14: config_type_tomato(g); return;
    case 15: config_type_wheat(g); return;
  }
}

