int foundry_crop_type_find(const char *name) {
  static const char *const names[] = {"barley", "beans", "cabbage", "carrot", "flax", "grapes", "lavender", "lettuce", "maize", "oats", "onion", "potato", "pumpkin", "sunflower", "tomato", "wheat"};
  for (int i = 0; name && i < 16; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

int foundry_crop_size_find(const char *name) {
  static const char *const names[] = {"small", "medium", "large"};
  for (int i = 0; name && i < 3; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

int foundry_crop_growth_find(const char *name) {
  static const char *const names[] = {"sown", "sprouting", "growing", "ripe", "harvested"};
  for (int i = 0; name && i < 5; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

int foundry_crop_season_find(const char *name) {
  static const char *const names[] = {"winter", "spring", "summer", "fall"};
  for (int i = 0; name && i < 4; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

int foundry_crop_detail_find(const char *name) {
  static const char *const names[] = {"high", "medium", "low"};
  for (int i = 0; name && i < 3; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

foundry_status foundry_crop_get_result(foundry_runtime *rt, foundry_instance instance, foundry_crop_result *out) {
  uint32_t bits = 0;
  const runtime::Status st = rt->world.result(instance, bits);
  if (st != runtime::Status::ok) return foundry_status_of(st);
  if (!out) return FOUNDRY_OK;
  out->ready = (bits & runtime::World::kResultReady) != 0;
  return FOUNDRY_OK;
}

